 * derivation should use is exactly the question task 1.4 has to answer.
 */
import { browser } from '@wdio/globals';
import { obsidianPage } from 'wdio-obsidian-service';
import * as fs from 'node:fs';
import * as path from 'node:path';
import * as h from '../helpers.js';

const OUT = path.join(process.cwd(), '.obsidian-cache', 'marker-gap-probe');

interface MarkReading {
  /** Which line of the fixture, and what it is. */
  n: number;
  label: string;
  /** `depth * unit`, the x every mark is supposed to be centred on. */
