  surface: 'editor' | 'footer';
  theme: 'light' | 'dark';
  fixture: string;
  /** Resolved values the arithmetic is stated in. */
  remPx: number;
  unit: number;
  gutter: number;
  iconSize: number;
  spaceAdvance: string;
