  if (!parts.length) return null;
  const l = Math.min(...parts.map((r) => r.left));
  const r = Math.max(...parts.map((r) => r.right));
  return { l: +(l - frameLeft).toFixed(2), r: +(r - frameLeft).toFixed(2) };
