        // The row's own text: first ink, chrome spans excluded — the same walk
        // 56-list-grid uses, for the same reason (a leading tab is not always
        // wrapped, and a task's content span opens with a space).
        const range = document.createRange();
        const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
        let textX: number | null = null;
        let node: Node | null = walker.nextNode();
        while (node) {
          const chrome = node.parentElement?.closest(
            '.cm-formatting-list, .cm-hmd-list-indent, .task-list-label, .to-decor-marker-icon',
          );
          const raw = node.textContent ?? '';
          if (!chrome && raw.trim() !== '') {
            range.setStart(node, raw.length - raw.trimStart().length);
            range.setEnd(node, raw.length);
            for (const r of Array.from(range.getClientRects())) {
              if (r.width === 0) continue;
              const left = +(r.left - cb.left).toFixed(2);
              if (textX === null || left < textX) textX = left;
            }
          }
          node = walker.nextNode();
        }

        const bullet = el.querySelector(':scope .list-bullet');
        const checkbox = el.querySelector(':scope .task-list-item-checkbox');
        const ol = el.querySelector(':scope .to-decor-ol-digits, :scope .cm-formatting-list-ol');
        const icon = el.querySelector(':scope > .to-decor-marker-icon');

        let label = 'other';
        let box: { l: number; r: number } | null = null;
        let ink: { l: number; r: number } | null = null;
        if (checkbox) {
          label = 'checkbox';
          box = boxOf(checkbox);
          ink = box; // an <input> paints its own border box
        } else if (ol) {
          label = 'ordered';
          box = boxOf(ol);
          ink = inkOfGlyphs(ol);
        } else if (bullet) {
          label = 'bullet';
          // Zero-width box; the dot is an absolutely positioned `::after`.
          const after = getComputedStyle(bullet, '::after');
          const br = bullet.getBoundingClientRect();
          const l = br.left - cb.left + (parseFloat(after.left) || 0);
          const w = parseFloat(after.width) || 0;
          box = boxOf(bullet);
          ink = { l: +l.toFixed(2), r: +(l + w).toFixed(2) };
        } else if (icon) {
          label = 'block-icon';
          box = boxOf(icon);
          ink = inkOfSvg(icon);
        } else {
          continue;
        }

        rows.push({
          n,
          label: `${label}: ${cm.state.doc.line(n + 1).text.trim().slice(0, 28)}`,
          column: +(depth * unit).toFixed(2),
          textX,
          box,
          ink,
        });
      }
      return {
        surface: 'editor' as const,
        theme,
        fixture,
        remPx,
        unit,
        gutter: px(cs.getPropertyValue('--to-marker-gutter') || '0'),
        iconSize: px(cs.getPropertyValue('--to-marker-icon-size') || '0'),
        spaceAdvance: cs.getPropertyValue('--to-space-advance').trim() || '<unset>',
        rows,
      };
    },
    fixture,
    theme,
  );
}

function footerPass(fixture: string, theme: 'light' | 'dark'): Promise<Pass> {
  return browser.executeObsidian(
    (_ctx, fixture: string, theme: 'light' | 'dark') => {
      const root = document.querySelector<HTMLElement>('.workspace-leaf.mod-active .to-backlinks');
      if (!root) throw new Error('no footer rendered');
      const remPx = parseFloat(getComputedStyle(document.documentElement).fontSize);
      const px = (raw: string): number => {
        const v = raw.trim();
        if (v.endsWith('rem')) return parseFloat(v) * remPx;
        return parseFloat(v);
      };
      const rootStyle = getComputedStyle(root);
      const unit = px(rootStyle.getPropertyValue('--to-decor-unit'));

      const rowEls = Array.from(root.querySelectorAll<HTMLElement>('.to-backlinks-row'));
      if (!rowEls.length) throw new Error('footer has no rows');
      // Every row's border box starts at the section's own content edge, so one
      // row's left is the frame every column is stated in.
      const frameLeft = rowEls[0]!.getBoundingClientRect().left;

      const inkOfSvg = (host: Element | null): { l: number; r: number } | null => {
        if (!host) return null;
        const svg = host.tagName.toLowerCase() === 'svg' ? host : host.querySelector('svg');
        if (!svg) return null;
        const parts = Array.from(svg.children)
          .map((c) => c.getBoundingClientRect())
          .filter((r) => r.width > 0);
        if (!parts.length) return null;
        return {
          l: +(Math.min(...parts.map((r) => r.left)) - frameLeft).toFixed(2),
          r: +(Math.max(...parts.map((r) => r.right)) - frameLeft).toFixed(2),
        };
      };
      const inkOfGlyphs = (host: Element | null): { l: number; r: number } | null => {
        if (!host) return null;
        const range = document.createRange();
        const walker = document.createTreeWalker(host, NodeFilter.SHOW_TEXT);
        const parts: DOMRect[] = [];
        let node: Node | null = walker.nextNode();
        while (node) {
          const raw = node.textContent ?? '';
          if (raw.trim() !== '') {
            range.setStart(node, raw.length - raw.trimStart().length);
            range.setEnd(node, raw.trimEnd().length);
            for (const r of Array.from(range.getClientRects())) if (r.width > 0) parts.push(r);
          }
          node = walker.nextNode();
        }
        if (!parts.length) return null;
        return {
          l: +(Math.min(...parts.map((r) => r.left)) - frameLeft).toFixed(2),
          r: +(Math.max(...parts.map((r) => r.right)) - frameLeft).toFixed(2),
        };
      };
      const boxOf = (el: Element | null): { l: number; r: number } | null => {
        if (!el) return null;
        const r = el.getBoundingClientRect();
        return { l: +(r.left - frameLeft).toFixed(2), r: +(r.right - frameLeft).toFixed(2) };
      };

      const rows: MarkReading[] = [];
      rowEls.forEach((el, i) => {
        const depth = Number(el.style.getPropertyValue('--to-depth').trim() || '0');
        const ordinal = el.querySelector(':scope > .to-backlinks-ordinal');
        const icon = el.querySelector(':scope > .to-decor-marker-icon');
        const mark = ordinal ?? icon;
        if (!mark) return;

        // The row's own text: everything after the mark.
        const range = document.createRange();
        const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
        let textX: number | null = null;
        let node: Node | null = walker.nextNode();
        while (node) {
          const chrome = node.parentElement?.closest(
            '.to-decor-marker-icon, .to-backlinks-ordinal, .to-backlinks-lineage',
          );
          const raw = node.textContent ?? '';
          if (!chrome && raw.trim() !== '') {
            range.setStart(node, raw.length - raw.trimStart().length);
            range.setEnd(node, raw.length);
            for (const r of Array.from(range.getClientRects())) {
              if (r.width === 0) continue;
              const left = +(r.left - frameLeft).toFixed(2);
              if (textX === null || left < textX) textX = left;
            }
          }
          node = walker.nextNode();
        }

        const isOrdinal = ordinal !== null;
        const isTask = icon?.querySelector('path[d^="M2.8 2.8"]') != null;
        rows.push({
          n: i,
          label: `${isOrdinal ? 'ordinal' : isTask ? 'checkbox-glyph' : 'block-icon'}: ${(el.textContent ?? '').trim().slice(0, 28)}`,
          column: +(depth * unit).toFixed(2),
          textX,
          box: boxOf(mark),
          ink: isOrdinal ? inkOfGlyphs(mark) : inkOfSvg(mark),
        });
      });

      const rowStyle = getComputedStyle(rowEls[0]!);
      return {
        surface: 'footer' as const,
        theme,
        fixture,
        remPx,
        unit,
        gutter: px(rowStyle.getPropertyValue('--to-marker-gutter') || '0'),
        // `em` on the footer root, so read it from a ROW where it resolves.
        iconSize: parseFloat(rowStyle.getPropertyValue('--to-marker-icon-size') || '0'),
        spaceAdvance: rowStyle.getPropertyValue('--to-space-advance').trim() || '<unset>',
        rows,
      };
    },
    fixture,
    theme,
  );
}

/** One pass as a table a human can read without a JSON viewer. */
function render(pass: Pass): string {
  const head =
    `\n=== ${pass.surface} / ${pass.theme} / ${pass.fixture}\n` +
    `    rem=${pass.remPx} unit=${pass.unit} gutter=${pass.gutter} ` +
    `icon=${pass.iconSize} space-advance=${pass.spaceAdvance}\n` +
    `    ${'mark'.padEnd(44)} ${'col'.padStart(7)} ${'inkL-col'.padStart(9)} ` +
    `${'inkR-col'.padStart(9)} ${'boxR-col'.padStart(9)} ${'textX-col'.padStart(9)} ${'text-inkR'.padStart(9)}\n`;
  const f = (v: number | null): string => (v === null ? '  —' : v.toFixed(2).padStart(9));
  return (
    head +
    pass.rows
      .map((r) => {
        const inkL = r.ink ? r.ink.l - r.column : null;
        const inkR = r.ink ? r.ink.r - r.column : null;
        const boxR = r.box ? r.box.r - r.column : null;
        const tx = r.textX === null ? null : r.textX - r.column;
        const gap = r.textX === null || r.ink === null ? null : r.textX - r.ink.r;
        return (
          `    ${r.label.padEnd(44)} ${r.column.toFixed(2).padStart(7)} ` +
          `${f(inkL)} ${f(inkR)} ${f(boxR)} ${f(tx)} ${f(gap)}`
        );
      })
      .join('\n')
  );
}

/** All four qualifying marks at one depth, plus the excluded multi-digit case. */
const ONE_SPACE = [
  '# H',
  '',
  'A paragraph.',
  '',
  '- a bulleted item',
  '',
  '- [ ] a task item',
  '',
  '1. an ordered item',
  '',
  '10. a wide ordered item',
  '',
].join('\n');

/** The same marks written with a tab after each, so `--to-space-advance` is not
 * the padding term the one-space rules apply. */
const TAB_SPACED = [
  '# H',
  '',
  'A paragraph.',
  '',
  '-\ta bulleted item',
  '',
  '-\t[ ] a task item',
  '',
  '1.\tan ordered item',
  '',
].join('\n');

const collected: Pass[] = [];

describe('PROBE: marker-to-text gap (throwaway)', function () {
